/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('.').glob('*.txt')):
 s=f.read_text(); pages=re.split(r'--- page (\\d+) ---',s)
 print('\\nFILE',f.name)
 for i in range(1,len(pages),2):
  p,t=pages[i:i+2]; lines=t.splitlines(); hits=[j for j,l in enumerate(lines) if re.search(r'audit|inspect|examin.*(?:book|record)',l,re.I)]
  selected=set()
  for j in hits: selected.update(range(max(0,j-3),min(len(lines),j+7)))
  if hits: print('PAGE',p, '\\n'+'\\n'.join(lines[j] for j in sorted(selected)))
PY"

